  'inv.daily': ['Stand der Ermittlung: {v} von 100 (heute +{d} durch den Verdacht). Bei 100 ist das Amt weg.', 'Investigation: {v} of 100 (+{d} today from suspicion). At 100 you lose the office.'],
  'rep.week2': ['Kapitel 2 ist vorbei. Inspektor Wyss schreibt seinen Bericht. Rang im Amt: {r}.', 'Chapter 2 is over. Inspector Wyss is writing his report. Rank in the office: {r}.'],
  'end2.title': ['Ende von Kapitel 2 · Der Bericht', 'End of chapter 2 · The report'],
  'end2.cleared': ['«Keine Hinweise auf ein Fehlverhalten.» Wyss gibt dir die Hand. Sie ist kalt. Im Dorf heisst es jetzt: Wer so sauber ist, muss gut sein. Oder sehr gut im Verstecken.', '“No evidence of misconduct.” Wyss shakes your hand. It is cold. The village now says: anyone this clean must be good. Or very good at hiding.'],
  'end2.scapegoat': ['Wyss findet einen Schuldigen: den Gemeindeschreiber. Er hat nichts getan, aber er hat alles unterschrieben. Du bleibst im Amt. Er nicht.', 'Wyss finds a culprit: the town clerk. He did nothing, but he signed everything. You stay in office. He does not.'],
  'end2.charged': ['Anklage. Du darfst bis zum Prozess im Amt bleiben, aber {p} muss den Wahlkampf mit deinem Foto in der Zeitung führen. Unter der Schlagzeile «Der Wolkenbetrüger».', 'Charged. You may stay in office until the trial, but {p} must run the campaign with your photo in the paper. Under the headline “The Cloud Fraudster”.'],
  'end2.betrayed': ['Anklage. Und Huber? Huber hat «leider nichts mehr tun können». Er steht beim Apéro und erzählt, er habe dich immer schon verdächtig gefunden.', 'Charged. And Huber? Huber “sadly couldn’t do anything”. He stands at the reception telling everyone he always found you suspicious.'],
  'end2.envelope': ['Wyss hat den Umschlag nie erwähnt. Er hat ihn aber auch nicht zurückgegeben. Das wird noch wichtig.', 'Wyss never mentioned the envelope. But he never gave it back either. That will matter.'],
  'end2.removed': ['Die Ermittlung hat 100 erreicht. Der Kanton enthebt dich deines Amtes. Wolkenwil bekommt einen Beamten aus der Stadt. Er macht nur rechteckige Wolken.', 'The investigation has reached 100. The canton removes you from office. Wolkenwil gets a civil servant from the city. He only makes rectangular clouds.'],
  'end2.removedMail': ['Verfügung des Kantons: Sie sind Ihres Amtes enthoben. Ihr Schlüssel liegt beim Gemeindeschreiber. Bitte nehmen Sie Ihre Pflanze mit.', 'Order of the canton: you are removed from office. Your key is with the town clerk. Please take your plant with you.'],
  'end2.retry': ['Kapitel 2 neu beginnen', 'Restart chapter 2'],
  'end2.retryRes': ['Du wachst auf. Es ist wieder Montag. Der Einschreibebrief liegt noch ungeöffnet auf dem Pult.', 'You wake up. It is Monday again. The registered letter is still unopened on the desk.'],
